effects.shader:
@fragment
fn fs(@location(0) uv : vec2<f32>) -> @location(0) vec4<f32> {
  let luma = vec3<f32>(0.299, 0.587, 0.114);

  // Direction and size of the apparent camera move. 0.08 keeps the useful
  // range of `depth` around 1 instead of around 0.01.
  let dir = vec2<f32>(params.shiftX, params.shiftY) * params.depth * 0.08;

  // Walk toward the displaced sample. One step already looks like parallax;
  // it just smears where the height changes fast, because the offset is taken
  // from the height at the WRONG point. Each pass re-reads the height where it
  // last landed and re-solves. Four is where it stops visibly improving.
  //
  // The bound is a literal because the validator refuses a loop it cannot
  // cost, and `textureSampleLevel` avoids depending on implicit derivatives.
  var p = uv;
  for (var i : i32 = 0; i < 4; i = i + 1) {
    let h = dot(textureSampleLevel(src, samp, p, 0.0).rgb, luma);
    p = uv + dir * (h - params.focus);
  }

  // Off-image samples clamp to the edge and streak. Fading them out reads as
  // the picture ending rather than as a smear, which is the honest look.
  let edge = min(min(p.x, 1.0 - p.x), min(p.y, 1.0 - p.y));
  let fade = clamp(edge * 40.0, 0.0, 1.0);

  return textureSampleLevel(src, samp, p, 0.0) * fade;
}
